'use client';

import { useState, ReactNode, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useRouter, useSearchParams, usePathname } from 'next/navigation';

function ChromeCloseIcon() {
    return (
        <svg width="10" height="10" viewBox="0 0 10 10" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path d="M1 1L9 9M9 1L1 9" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
        </svg>
    );
}

function GlobeIcon() {
    return (
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
            <circle cx="12" cy="12" r="10" />
            <path d="M2 12h20" />
            <path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z" />
        </svg>
    );
}

export interface Tab {
    id: string;
    title: string;
    icon?: ReactNode;
    content: ReactNode;
    type: 'home' | 'detail';
}

interface TabSystemProps {
    initialTab: Tab;
    allTabs?: Record<string, Tab>; // Map of available detail tabs passed from ClientPage
}

export default function TabSystem({ initialTab, allTabs = {} }: TabSystemProps) {
    const router = useRouter();
    const pathname = usePathname();
    const searchParams = useSearchParams();

    // Parse the current `tabs` from URL: "?tabs=[acko,frontrow]"
    const getTabsFromUrl = useCallback((): string[] => {
        const tabsParam = searchParams.get('tabs');
        if (!tabsParam) return [];
        // Extract array from brackets, e.g. "[acko,frontrow]" -> "acko,frontrow"
        const matched = tabsParam.match(/^\[(.*)\]$/);
        const csvList = matched ? matched[1] : tabsParam;
        if (!csvList.trim()) return [];
        return csvList.split(',').map(s => s.trim()).filter(Boolean);
    }, [searchParams]);

    // Internal state that respects URL
    const [tabs, setTabs] = useState<Tab[]>([initialTab]);
    const [activeTabId, setActiveTabId] = useState<string>(initialTab.id);

    // Sync state with URL
    useEffect(() => {
        const tabIds = getTabsFromUrl();
        const activeUrlTab = searchParams.get('active');

        const newTabs = [initialTab];
        let newActiveId = initialTab.id;

        tabIds.forEach(id => {
            if (allTabs[id]) {
                newTabs.push(allTabs[id]);
                newActiveId = id; // Default latest tab as active
            }
        });

        if (activeUrlTab && newTabs.some(t => t.id === activeUrlTab)) {
            newActiveId = activeUrlTab;
        }

        setTabs(newTabs);
        setActiveTabId(newActiveId);
    }, [searchParams, allTabs, initialTab, getTabsFromUrl]);

    // Handle "on back navigation from any tab, intercept it and go to home page"
    useEffect(() => {
        const handlePopState = (e: PopStateEvent) => {
            // We want to force going to the home page to satisfy the intercept requirement
            const search = new URLSearchParams(window.location.search);
            if (search.get('tabs')) {
                // If it was a back to another tab state, intercept and override to home
                router.replace(pathname);
            }
        };
        window.addEventListener('popstate', handlePopState);
        return () => window.removeEventListener('popstate', handlePopState);
    }, [router, pathname]);

    const updateUrl = (tabIds: string[], newActiveId?: string) => {
        const params = new URLSearchParams(Array.from(searchParams.entries()));

        if (tabIds.length > 0) {
            params.set('tabs', `[${tabIds.join(',')}]`);
        } else {
            params.delete('tabs');
        }

        if (newActiveId && newActiveId !== initialTab.id) {
            params.set('active', newActiveId);
        } else {
            params.delete('active');
        }

        const query = params.toString();
        const url = `${pathname}${query ? `?${query}` : ''}`;

        // append to the history stack
        router.push(url);
    };

    useEffect(() => {
        // We redefine CustomEvent handling to add tab ID
        const handleOpenTab = (e: CustomEvent<string>) => {
            const newTabId = e.detail;
            if (!allTabs[newTabId]) return;

            const currentIds = tabs.map(t => t.id).filter(id => id !== initialTab.id);
            if (!currentIds.includes(newTabId)) {
                currentIds.push(newTabId); // append to stack
            }
            updateUrl(currentIds, newTabId);
        };

        window.addEventListener('open-tab', handleOpenTab as EventListener);
        return () => window.removeEventListener('open-tab', handleOpenTab as EventListener);
    }, [tabs, allTabs, initialTab, updateUrl]);

    const closeTab = (e: React.MouseEvent, id: string) => {
        e.stopPropagation();
        if (id === initialTab.id) return; // Cannot close home tab

        const currentIds = tabs.map(t => t.id).filter(tId => tId !== initialTab.id && tId !== id);

        let newActiveId = undefined;
        if (activeTabId === id && tabs.length > 1) {
            // Revert active tab logic
            const idx = tabs.findIndex(t => t.id === id);
            if (idx > 0) newActiveId = tabs[idx - 1].id;
        } else {
            newActiveId = activeTabId;
        }

        updateUrl(currentIds, newActiveId);
    };

    const handleTabSelect = (id: string) => {
        const currentIds = tabs.map(t => t.id).filter(tId => tId !== initialTab.id);
        updateUrl(currentIds, id);
    };

    return (
        <div className="flex flex-col h-screen overflow-hidden bg-[var(--cream-200)] font-sans text-[var(--text-primary)]">
            {/* Tab Bar - Only show if > 1 tab */}
            {tabs.length > 1 && (
                <div className="flex items-end pt-2 px-2 bg-[#dfe1e5] gap-1 select-none" style={{ height: '40px' }}>
                    <div className="flex-1 flex gap-1 overflow-x-auto no-scrollbar items-end">
                        <AnimatePresence initial={false}>
                            {tabs.map((tab) => {
                                const isActive = tab.id === activeTabId;
                                return (
                                    <motion.div
                                        key={tab.id}
                                        layout
                                        initial={{ opacity: 0, scale: 0.9, x: -20 }}
                                        animate={{ opacity: 1, scale: 1, x: 0 }}
                                        exit={{ opacity: 0, scale: 0.9, width: 0 }}
                                        onClick={() => handleTabSelect(tab.id)}
                                        className={`
                                            group relative flex items-center gap-2 pl-3 pr-2 py-2 min-w-[140px] max-w-[200px] h-[34px] 
                                            rounded-t-lg transition-all cursor-default text-xs
                                            ${isActive ? 'bg-[var(--cream-50)] shadow-sm z-10' : 'bg-transparent hover:bg-white/40 text-[var(--text-secondary)]'}
                                        `}
                                    >
                                        <span className={`opacity-80 ${isActive ? 'text-blue-600' : ''}`}>
                                            {tab.icon || <GlobeIcon />}
                                        </span>

                                        <span className="flex-1 truncate font-medium">
                                            {tab.title}
                                        </span>

                                        {tab.id !== initialTab.id && (
                                            <button
                                                onClick={(e) => closeTab(e, tab.id)}
                                                className={`
                                                    p-1 rounded-full hover:bg-[var(--cream-300)] opacity-0 group-hover:opacity-100 transition-opacity
                                                    ${isActive ? 'opacity-100' : ''}
                                                `}
                                            >
                                                <ChromeCloseIcon />
                                            </button>
                                        )}
                                    </motion.div>
                                );
                            })}
                        </AnimatePresence>
                    </div>
                </div>
            )}

            {/* Content Area */}
            <div className="flex-1 relative overflow-hidden bg-[var(--cream-50)]">
                {tabs.map((tab) => (
                    <div
                        key={tab.id}
                        id={`tab-content-${tab.id}`}
                        className="absolute inset-0 w-full h-full overflow-y-auto overflow-x-hidden scroll-smooth"
                        style={{
                            display: activeTabId === tab.id ? 'block' : 'none',
                            zIndex: activeTabId === tab.id ? 1 : 0
                        }}
                    >
                        {tab.content}
                    </div>
                ))}
            </div>
        </div>
    );
}

export function dispatchOpenTab(id: string) {
    if (typeof window !== 'undefined') {
        const event = new CustomEvent('open-tab', { detail: id });
        window.dispatchEvent(event);
    }
}
